{"cards": [{"node_code": "N_e63e64499d4791a5", "definition": "研究土木工程材料在试验前从工程实体或原材料堆中获取代表性样本，以及将样本加工、成型为符合标准尺寸和形状试件的技术过程与方法。", "boundary": "本节点聚焦于试验前的“准备阶段”，即如何获取具有代表性的材料样本（取样）以及如何将其转化为可测试的试件（制备）。涵盖取样方案、器具、频率及试件模具、养护条件等。与“材料力学性能试验”的区别在于，本节点不涉及加载测试过程，仅关注测试前的状态准备；与“材料质量评价”的区别在于，本节点侧重物理操作过程，而非数据判定。", "includes": ["各类建材（混凝土、沥青、钢材等）的取样方法、器具及代表性要求", "试件成型工艺、模具规格、脱模及标准养护条件", "取样与制备过程中的质量控制要点及常见误差分析"], "excludes": ["试件成型后的力学加载、物理性质测试及数据分析（归入具体试验类型节点）", "基于试验结果的材料合格性判定与质量验收（归入材料质量评价与检验判定）", "材料配合比设计或原材料本身的化学组成分析（归入具体材料类别）"], "sibling_distinctions": [{"other_code": "N_5bf6feae7c2ab4f3", "rule": "本节点侧重“测前准备”（取样与成型）；兄弟节点侧重“测中过程”（加载与读数）。"}, {"other_code": "N_bdbb9bfd27798cdc", "rule": "本节点侧重物理操作规范；兄弟节点侧重基于数据的统计判定与标准符合性评价。"}], "cross_boundary_rule": "若内容涉及取样频率、器具校准或试件养护制度，归本节点；若涉及试件在试验机上的受力行为或测试步骤，归入相应性能试验节点。"}, {"node_code": "N_0b10dec38abb9675", "definition": "研究土木工程中骨料（砂、石、矿粉等）的物理特性、颗粒级配分布及其对材料性能影响的试验方法与评价技术。", "boundary": "本节点专门针对“骨料”这一特定材料组分，涵盖其颗粒形状、表面纹理、含泥量、针片状含量等物理指标测试，以及通过筛分等手段确定级配曲线的过程。与“基本物理性质试验”的区别在于，本节点聚焦于颗粒状材料的级配与形态特征，而非块体材料的密度、吸水率等通用指标；与“混凝土与砂浆试验”的区别在于，本节点仅针对骨料本身，不涉及胶凝材料或混合后的整体性能。", "includes": ["骨料颗粒级配筛分试验、级配曲线绘制及空隙率计算", "骨料物理性质测试（含泥量、泥块含量、针片状含量、压碎值等）", "细骨料与粗骨料的分类标准及级配优化方法"], "excludes": ["胶凝材料（水泥、粉煤灰等）的性能试验（归入水泥技术性能试验或相关节点）", "混凝土或砂浆整体配合比设计及工作性测试（归入混凝土与砂浆试验）", "骨料在长期环境下的耐久性劣化机理研究（归入材料性能、耐久与防护）"], "sibling_distinctions": [{"other_code": "N_250af9c14f63000f", "rule": "本节点侧重颗粒状材料的级配与形态；兄弟节点侧重块体或均质材料的密度、含水率等通用物理指标。"}, {"other_code": "N_a357544ccfea658b", "rule": "本节点仅测试骨料组分；兄弟节点测试由骨料、胶凝材料和水组成的混凝土/砂浆整体。"}], "cross_boundary_rule": "若试验对象为单一颗粒组分且关注其粒径分布或形态指标，归本节点；若试验对象为混合料整体或关注胶凝材料反应，归入相应混合料或胶凝材料节点。"}, {"node_code": "N_5bf6feae7c2ab4f3", "definition": "研究土木工程材料在静力或动力荷载作用下，其强度、弹性、塑性、韧性及破坏模式等力学行为的试验方法与测试技术。", "boundary": "本节点聚焦于材料在受力状态下的响应，涵盖抗压、抗拉、抗弯、抗剪、疲劳及冲击等力学性能测试。与“基本物理性质试验”的区别在于，本节点涉及荷载作用与变形测量，而非无荷载下的密度、孔隙率等静态指标；与“材料质量评价”的区别在于，本节点侧重获取力学数据的过程，而非基于数据的合格性判定。", "includes": ["材料抗压、抗拉、抗弯、抗剪等静力力学性能试验方法", "材料疲劳、冲击、断裂韧性等动力或复杂应力状态下的力学测试", "力学试验中的加载制度、应变测量及破坏模式分析"], "excludes": ["无荷载作用下的密度、吸水率、孔隙率等物理性质测试（归入基本物理性质试验）", "基于力学试验结果的材料等级划分与质量验收判定（归入材料质量评价与检验判定）", "结构构件或整体结构在荷载下的受力分析与设计（归入建筑与结构工程）"], "sibling_distinctions": [{"other_code": "N_250af9c14f63000f", "rule": "本节点侧重“受力响应”（强度、变形）；兄弟节点侧重“静态属性”（密度、含水率）。"}, {"other_code": "N_bdbb9bfd27798cdc", "rule": "本节点侧重力学数据的获取过程；兄弟节点侧重利用数据进行的统计分析与标准符合性判定。"}], "cross_boundary_rule": "若内容涉及加载设备、加载速率、应力-应变曲线获取，归本节点；若内容涉及无荷载下的物理参数测量，归入基本物理性质试验；若涉及结果判定，归入质量评价节点。"}]}
